export interface ElementProps {
  disabled?: boolean;
  [key: string]: unknown;
}

/**
 * Adapts props for accessibility based on the component type
 * @param props The original props object
 * @param elementType The type of element to adapt props for
 * @returns The adapted props with appropriate accessibility attributes
 */
export function adaptPropsForA11y(
  props: ElementProps,
  elementType: string,
): ElementProps {
  const { disabled, ...rest } = props;

  // For non-button elements, use aria-disabled instead of the disabled attribute
  if (
    disabled &&
    elementType !== "button" &&
    elementType !== "input" &&
    elementType !== "select" &&
    elementType !== "textarea"
  ) {
    return {
      "aria-disabled": "true",
      ...rest,
    };
  }

  return props;
}

import { TemplateRef } from "@angular/core";

export interface TabBaseProps {
  /**
   * The content of the component.
   */
  // children are handled by Angular's content projection

  /**
   * If true, the component is disabled.
   * @default false
   */
  disabled?: boolean;

  /**
   * The icon to display.
   */
  icon?: TemplateRef<any> | null;

  /**
   * The label for the tab.
   */
  label?: string;

  /**
   * You can provide your own value. Otherwise, we fallback to the child position index.
   */
  value: any;

  /**
   * If true, the tab will have a ripple effect when clicked.
   * @default true
   */
  disableRipple?: boolean;

  /**
   * Override or extend the styles applied to the component.
   */
  className?: string;

  /**
   * If true, the keyboard focus ripple is disabled.
   * @default false
   */
  disableFocusRipple?: boolean;
}

export interface TabListBaseProps {
  /**
   * Override or extend the styles applied to the component.
   */
  className?: string;

  /**
   * The component orientation (layout flow direction).
   * @default 'horizontal'
   */
  orientation?: "horizontal" | "vertical";

  /**
   * If true, the scrollbar is visible.
   * @default false
   */
  visibleScrollbar?: boolean;

  /**
   * If true, the tabs will be centered.
   * @default false
   */
  centered?: boolean;

  /**
   * The variant to use.
   * @default 'standard'
   */
  variant?: "standard" | "contained" | "borderless";

  /**
   * The size of the component.
   * @default 'md'
   */
  size?: "sm" | "md" | "lg";
}

export interface TabPanelBaseProps {
  /**
   * The value of the corresponding tab. Must match the value of the tab in the tab list.
   */
  value: any;

  /**
   * Override or extend the styles applied to the component.
   */
  className?: string;

  /**
   * The id of the tab panel.
   */
  id?: string;

  /**
   * Callback fired when the panel is visible.
   */
  onEnter?: () => void;

  /**
   * Callback fired when the panel is hidden.
   */
  onExit?: () => void;

  /**
   * If true, the panel will be displayed with a fade animation.
   * @default true
   */
  animate?: boolean;

  /**
   * If true, the panel will be mounted when hidden.
   * @default false
   */
  keepMounted?: boolean;

  /**
   * The variant of the tab panel.
   * @default 'standard'
   */
  variant?: "standard" | "boxed" | "borderless";

  /**
   * The animation type to use when transitioning.
   * @default 'fade'
   */
  animation?: "fade" | "slide" | "none";
}

import { EventEmitter } from "@angular/core";

export interface TabsBaseProps {
  /**
   * Callback fired when the value changes.
   */
  valueChange?: EventEmitter<any>;

  /**
   * The value of the currently selected tab.
   */
  value?: any;

  /**
   * The default value. Use when the component is not controlled.
   */
  defaultValue?: any;

  /**
   * The orientation of the tabs.
   * @default 'horizontal'
   */
  orientation?: "horizontal" | "vertical";

  /**
   * Determines the tabs display variant.
   * @default 'standard'
   */
  variant?: "standard" | "scrollable" | "fullWidth";

  /**
   * Determines the color of the indicator.
   * @default 'primary'
   */
  indicatorColor?: "primary" | "secondary";

  /**
   * Determines the color of the text.
   * @default 'inherit'
   */
  textColor?: "inherit" | "primary" | "secondary";

  /**
   * Custom class name
   */
  className?: string;

  /**
   * Aria label for the tabs container
   */
  ["aria-label"]?: string | null;
}

