import { Component } from "@angular/core";
import { RouterOutlet } from "@angular/router";

@Component({
  selector: "app-root",
  standalone: true,
  imports: [RouterOutlet],
  templateUrl: "./app.component.html",
})
export class AppComponent {
  title = "angular-xui";
}

import { Component } from "@angular/core";
import { TabsComponent } from "../Tabs";
import { TabListComponent } from "../TabList";
import { TabComponent } from "../Tab/Tab.component";
import { TabPanelComponent } from "./TabPanel.component";

@Component({
  selector: "basic-test",
  standalone: true,
  imports: [TabsComponent, TabListComponent, TabComponent, TabPanelComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">Tab 1</xui-tab>
        <xui-tab [value]="1">Tab 2</xui-tab>
      </xui-tablist>
      <xui-tabpanel [value]="0">Panel Content 1</xui-tabpanel>
      <xui-tabpanel [value]="1">Panel Content 2</xui-tabpanel>
    </xui-tabs>
  `,
})
class BasicTabPanelTestComponent {}

@Component({
  selector: "custom-class-test",
  standalone: true,
  imports: [TabsComponent, TabListComponent, TabComponent, TabPanelComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">Tab 1</xui-tab>
      </xui-tablist>
      <xui-tabpanel [value]="0" className="custom-class">
        Panel Content
      </xui-tabpanel>
    </xui-tabs>
  `,
})
class CustomClassTabPanelTestComponent {}

describe("TabPanel Component", () => {
  it("renders tab panel correctly", () => {
    cy.mount(BasicTabPanelTestComponent);

    cy.get('[role="tabpanel"]')
      .should("exist")
      .and("contain.text", "Panel Content 1");
  });

  it("shows the correct panel when tab is selected", () => {
    cy.mount(BasicTabPanelTestComponent);

    // Click second tab
    cy.get('[role="tab"]').eq(1).click();

    // Second panel should be visible
    cy.get('[role="tabpanel"]').should("contain.text", "Panel Content 2");
  });

  it("renders with custom className", () => {
    cy.mount(CustomClassTabPanelTestComponent);

    cy.get('[role="tabpanel"]').should("have.class", "custom-class");
  });

  it("properly hides inactive panels", () => {
    cy.mount(BasicTabPanelTestComponent);

    // First panel should be visible, second hidden
    cy.get('[role="tabpanel"]').first().should("be.visible");
    cy.get('[role="tabpanel"]').eq(1).should("not.be.visible");
  });
});

import {
  Component,
  Input,
  Output,
  EventEmitter,
  TemplateRef,
  ChangeDetectionStrategy,
} from "@angular/core";
import { CommonModule } from "@angular/common";
import { buttonVariants } from "./variants";
import { ButtonBaseProps } from "./button.types";

@Component({
  selector: "app-button",
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: "./button.component.html",
  styleUrls: [],
})
export class ButtonComponent implements ButtonBaseProps {
  @Input() variant: "text" | "contained" | "outlined" = "contained";
  @Input() color:
    | "inherit"
    | "primary"
    | "secondary"
    | "success"
    | "error"
    | "info"
    | "warning" = "primary";
  @Input() size: "small" | "medium" | "large" = "medium";
  @Input() disabled: boolean = false;
  @Input() loading: boolean = false;
  @Input() loadingPosition: "start" | "center" | "end" = "center";
  @Input() fullWidth: boolean = false;
  @Input() disableElevation: boolean = false;
  @Input() component: string = "button";
  @Input() type: "button" | "submit" | "reset" = "button";
  @Input() href?: string;
  @Input() target?: string;
  @Input() role?: string;
  @Input() startIcon?: TemplateRef<unknown>;
  @Input() endIcon?: TemplateRef<unknown>;
  @Input() customLoadingIndicator?: TemplateRef<unknown>;
  @Output() clicked = new EventEmitter<void>();

  get isDisabled(): boolean {
    return this.disabled || this.loading;
  }

  get buttonClasses(): string {
    return buttonVariants({
      variant: this.variant,
      color: this.color,
      size: this.size,
      fullWidth: this.fullWidth,
      disableElevation: this.disableElevation,
    });
  }

  handleClick() {
    if (!this.isDisabled) {
      this.clicked.emit();
    }
  }
}

import { TabComponent } from "./Tab.component";
import { TabsComponent } from "../Tabs/tabs.component";
import { Component } from "@angular/core";
import { TabListComponent } from "../TabList";

@Component({
  selector: "test-wrapper",
  standalone: true,
  imports: [TabsComponent, TabComponent, TabListComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">Standard Tab</xui-tab>
      </xui-tablist>
    </xui-tabs>
  `,
})
class StandardTabTestComponent {}

@Component({
  selector: "icon-tab-wrapper",
  standalone: true,
  imports: [TabsComponent, TabComponent, TabListComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">
          <span data-testid="icon">🏠</span>
          With Icon
        </xui-tab>
      </xui-tablist>
    </xui-tabs>
  `,
})
class IconTabTestComponent {}

@Component({
  selector: "disabled-tab-wrapper",
  standalone: true,
  imports: [TabsComponent, TabComponent, TabListComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">Tab 1</xui-tab>
        <xui-tab [value]="1" [disabled]="true">Disabled Tab</xui-tab>
      </xui-tablist>
    </xui-tabs>
  `,
})
class DisabledTabTestComponent {}

@Component({
  selector: "click-event-wrapper",
  standalone: true,
  imports: [TabsComponent, TabComponent, TabListComponent],
  template: `
    <xui-tabs [defaultValue]="0">
      <xui-tablist>
        <xui-tab [value]="0">Tab 1</xui-tab>
        <xui-tab [value]="1">Tab 2</xui-tab>
      </xui-tablist>
    </xui-tabs>
  `,
})
class ClickEventTabTestComponent {}

describe("TabComponent", () => {
  it("renders standard tab correctly", () => {
    cy.mount(StandardTabTestComponent);

    cy.get('[role="tab"]').should("exist").and("contain.text", "Standard Tab");
    cy.get('[role="tab"]').should("have.attr", "aria-selected", "true");
  });

  it("renders tab with icon", () => {
    cy.mount(IconTabTestComponent);

    cy.get('[data-testid="icon"]').should("exist");
    cy.get('[role="tab"]').should("contain.text", "With Icon");
  });

  it("renders disabled tab", () => {
    cy.mount(DisabledTabTestComponent);

    cy.get('[role="tab"]')
      .eq(1)
      .should("have.attr", "aria-disabled", "true")
      .should("have.attr", "tabindex", "-1");
  });

  it("handles click events", () => {
    cy.mount(ClickEventTabTestComponent);

    cy.get('[role="tab"]').eq(0).should("have.attr", "aria-selected", "true");
    cy.get('[role="tab"]').eq(1).should("have.attr", "aria-selected", "false");

    cy.get('[role="tab"]').eq(1).click();
    cy.get('[role="tab"]').eq(0).should("have.attr", "aria-selected", "false");
    cy.get('[role="tab"]').eq(1).should("have.attr", "aria-selected", "true");
  });

  it("applies appropriate styles based on state", () => {
    cy.mount(ClickEventTabTestComponent);

    cy.get('[role="tab"][aria-selected="true"]')
      .should("exist")
      .and("contain.text", "Tab 1");

    cy.get('[role="tab"][aria-selected="false"]')
      .should("exist")
      .and("contain.text", "Tab 2");
  });
});

