import {
  Component,
  ElementRef,
  Input,
  OnInit,
  HostListener,
  TemplateRef,
  ViewChild,
  AfterViewInit,
  ContentChild,
} from "@angular/core";
import { CommonModule } from "@angular/common";

import { TabsService } from "../Tabs";
import { TabBaseProps } from "./Tab.types";

@Component({
  selector: "xui-tab",
  standalone: true,
  imports: [CommonModule],
  templateUrl: "./Tab.component.html",
})
export class TabComponent implements OnInit, AfterViewInit, TabBaseProps {
  @Input() value!: any;
  @Input() disabled = false;
  @Input() icon: TemplateRef<any> | null = null;
  @Input() label?: string;
  @Input() className = "";
  @Input() disableRipple = false;
  @Input() disableFocusRipple = false;

  @ViewChild("tabButton") tabButtonRef!: ElementRef<HTMLButtonElement>;
  @ContentChild("iconTemplate") iconRef?: TemplateRef<any>;

  isSelected = false;
  index = 0;
  orientation: "horizontal" | "vertical" = "horizontal";
  variant: "standard" | "scrollable" | "fullWidth" = "standard";

  constructor(
    private tabsService: TabsService,
    public elementRef: ElementRef,
  ) {}

  ngOnInit(): void {
    this.tabsService.value$.subscribe((value) => {
      this.isSelected = this.value === value;
    });

    this.tabsService.orientation$.subscribe((orientation) => {
      this.orientation = orientation;
    });

    this.tabsService.variant$.subscribe((variant) => {
      this.variant = variant;
    });
  }

  ngAfterViewInit(): void {
    // Focus the selected tab initially
    if (this.isSelected) {
      setTimeout(() => this.tabButtonRef.nativeElement.focus());
    }
  }

  @HostListener("focus")
  onFocus(): void {
    if (!this.disabled) {
      this.tabButtonRef.nativeElement.focus();
    }
  }

  handleClick(): void {
    if (!this.disabled) {
      this.tabsService.setValue(this.value);
    }
  }

  generateClasses(): string {
    const baseClasses = `ring-offset-background inline-flex items-center justify-center rounded-md px-3 py-1.5 text-sm font-medium whitespace-nowrap transition-all
                         focus-visible:ring-ring focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none
                         ${this.disabled ? "disabled:pointer-events-none disabled:opacity-50" : ""}
                         ${this.isSelected ? "data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow" : ""}
                         ${this.orientation === "vertical" ? "w-full justify-start" : ""}
                         ${this.variant === "fullWidth" ? "flex-1" : ""}
                         ${this.className}`;

    return baseClasses;
  }
}

import {
  Component,
  ContentChildren,
  AfterContentInit,
  QueryList,
  Input,
  OnInit,
  ElementRef,
  OnDestroy,
  ViewChild,
} from "@angular/core";
import { CommonModule } from "@angular/common";

import { Subscription } from "rxjs";
import { TabsService } from "../Tabs";

import { TabComponent } from "../Tab/Tab.component";

import { TabListBaseProps } from "./TabList.types";
import { TABLIST_SIZES, TABLIST_VARIANTS } from "./variants";

@Component({
  selector: "xui-tablist",
  standalone: true,
  imports: [CommonModule],
  templateUrl: "./TabList.component.html",
})
export class TabListComponent
  implements OnInit, AfterContentInit, OnDestroy, TabListBaseProps
{
  @Input() variant: keyof typeof TABLIST_VARIANTS = "standard";
  @Input() size: keyof typeof TABLIST_SIZES = "md";
  @Input() className = "";
  @Input() visibleScrollbar = false;
  @Input() centered = false;

  @ContentChildren(TabComponent) tabs?: QueryList<TabComponent>;
  @ViewChild("tabsRef") tabsRef?: ElementRef<HTMLDivElement>;

  orientation: "horizontal" | "vertical" = "horizontal";
  tabsVariant: "standard" | "scrollable" | "fullWidth" = "standard";
  indicatorColor: "primary" | "secondary" = "primary";
  currentValue: any = null;

  indicatorPosition = { left: 0, width: 0, top: 0, height: 0 };
  private subscriptions: Subscription[] = [];

  constructor(
    private tabsService: TabsService,
    public elementRef: ElementRef,
  ) {}

  ngOnInit(): void {
    this.subscribeToTabsService();
  }

  private subscribeToTabsService(): void {
    this.subscriptions.push(
      this.tabsService.orientation$.subscribe((orientation) => {
        this.orientation = orientation;
        setTimeout(() => this.updateIndicator());
      }),

      this.tabsService.variant$.subscribe((variant) => {
        this.tabsVariant = variant;
      }),

      this.tabsService.indicatorColor$.subscribe((color) => {
        this.indicatorColor = color;
      }),

      this.tabsService.value$.subscribe((value) => {
        this.currentValue = value;
        setTimeout(() => this.updateIndicator());
        this.focusSelectedTab();
      }),
    );
  }

  ngAfterContentInit(): void {
    if (!this.tabs) return;

    this.initializeTabs();

    this.subscriptions.push(
      this.tabs.changes.subscribe(() => {
        this.initializeTabs();
      }),
    );
  }

  private initializeTabs(): void {
    if (!this.tabs) return;

    this.tabs.forEach((tab, index) => {
      tab.index = index;
    });

    setTimeout(() => this.updateIndicator());
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((sub) => sub.unsubscribe());
  }

  updateIndicator(): void {
    if (!this.tabs) return;

    const selectedTab = this.tabs.find(
      (tab) => tab.value === this.currentValue,
    );

    if (!selectedTab || !selectedTab.elementRef?.nativeElement) return;

    const tabElement = selectedTab.elementRef.nativeElement;
    const listRect = tabElement.parentElement?.getBoundingClientRect();

    if (!listRect) return;

    const tabRect = tabElement.getBoundingClientRect();

    this.indicatorPosition =
      this.orientation === "horizontal"
        ? {
            left: tabRect.left - listRect.left,
            width: tabRect.width,
            top: 0,
            height: 0,
          }
        : {
            left: 0,
            width: 0,
            top: tabRect.top - listRect.top,
            height: tabRect.height,
          };
  }

  focusSelectedTab(): void {
    if (!this.tabs || !this.tabsRef) return;

    setTimeout(() => {
      const tabElements = this.getTabElements();
      const selectedTab = this.findSelectedTabElement(tabElements);

      if (selectedTab instanceof HTMLElement) {
        selectedTab.focus();
      }
    });
  }

  private getTabElements(): Element[] {
    return Array.from(this.tabsRef?.nativeElement.children || []).filter(
      (child) =>
        child instanceof HTMLElement && child.getAttribute("role") === "tab",
    );
  }

  private findSelectedTabElement(elements: Element[]): HTMLElement | undefined {
    return elements.find(
      (tab) =>
        tab instanceof HTMLElement &&
        tab.getAttribute("aria-selected") === "true",
    ) as HTMLElement | undefined;
  }

  generateClasses(): string {
    const orientationClass =
      this.orientation === "vertical"
        ? "h-full flex-col rounded-md"
        : "h-10 rounded-md";

    const variantClass = this.getVariantClass();
    const sizeClass = this.getSizeClass();
    const layoutClasses = this.getLayoutClasses();

    return [
      "bg-muted inline-flex items-center justify-center rounded-md p-1",
      orientationClass,
      variantClass,
      sizeClass,
      layoutClasses,
      this.className,
    ]
      .filter(Boolean)
      .join(" ");
  }

  private getVariantClass(): string {
    switch (this.variant) {
      case "standard":
        return "border-b border-gray-200";
      case "contained":
      case "borderless":
        return "border-none";
      default:
        return "";
    }
  }

  private getSizeClass(): string {
    switch (this.size) {
      case "sm":
        return "gap-1";
      case "md":
        return "gap-2";
      case "lg":
        return "gap-4";
      default:
        return "";
    }
  }

  private getLayoutClasses(): string {
    const classes = [];

    if (this.tabsVariant === "fullWidth") {
      classes.push("w-full");
    }

    if (this.tabsVariant === "scrollable") {
      if (!this.visibleScrollbar) {
        classes.push("scrollbar-none");
      }
    }

    if (this.centered) {
      classes.push("justify-center");
    }

    return classes.join(" ");
  }
}

import {
  Component,
  Input,
  OnInit,
  OnDestroy,
  ElementRef,
  ChangeDetectorRef,
} from "@angular/core";
import { CommonModule } from "@angular/common";
import { Subscription } from "rxjs";
import { TabPanelBaseProps } from "./TabPanel.types";
import { TABPANEL_ANIMATIONS, TABPANEL_VARIANTS } from "./variants";
import { TabsService } from "../Tabs";

@Component({
  selector: "xui-tabpanel",
  standalone: true,
  imports: [CommonModule],
  templateUrl: "./TabPanel.component.html",
})
export class TabPanelComponent implements OnInit, OnDestroy, TabPanelBaseProps {
  @Input() value!: any;
  @Input() className: string = "";
  @Input() id?: string;
  @Input() animate: boolean = true;
  @Input() keepMounted: boolean = false;
  @Input() variant: keyof typeof TABPANEL_VARIANTS = "standard";
  @Input() animation: keyof typeof TABPANEL_ANIMATIONS = "fade";

  active = false;
  private subscription?: Subscription;

  constructor(
    private tabsService: TabsService,
    private elementRef: ElementRef,
    private cdr: ChangeDetectorRef,
  ) {}

  ngOnInit(): void {
    this.subscription = this.tabsService.value$.subscribe((value) => {
      const wasActive = this.active;
      this.active = this.value === value;

      if (this.active && !wasActive && this.onEnter) {
        this.onEnter();
      } else if (!this.active && wasActive && this.onExit) {
        this.onExit();
      }

      this.cdr.detectChanges();
    });
  }

  ngOnDestroy(): void {
    if (this.subscription) {
      this.subscription.unsubscribe();
    }
  }

  onEnter?(): void;
  onExit?(): void;

  generateClasses(): string {
    const baseClasses = `
      ring-offset-background 
      ${this.active ? "data-[state=active]:animate-in data-[state=active]:fade-in" : "data-[state=inactive]:animate-out data-[state=inactive]:fade-out"} 
      mt-2
      focus-visible:ring-ring focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none
      ${this.className}`;

    // Add variant classes
    let variantClass = "";
    switch (this.variant) {
      case "standard":
        variantClass = "p-4";
        break;
      case "boxed":
        variantClass = "p-4 border rounded-lg";
        break;
      case "borderless":
        variantClass = "p-4 border-0";
        break;
    }

    // Add animation classes
    let animationClass = "";
    if (this.animate) {
      switch (this.animation) {
        case "fade":
          animationClass = "transition-opacity duration-200";
          break;
        case "slide":
          animationClass = "transition-transform duration-200";
          break;
        case "none":
          animationClass = "";
          break;
      }
    }

    return `${baseClasses} ${variantClass} ${animationClass}`.trim();
  }
}

import {
  Component,
  ContentChildren,
  EventEmitter,
  Input,
  OnInit,
  Output,
  QueryList,
  AfterContentInit,
} from "@angular/core";
import { CommonModule } from "@angular/common";

import { TabsService } from "./Tabs.service";
import { TabsBaseProps } from "./Tabs.types";

import { TabListComponent } from "../TabList";
import { TabPanelComponent } from "../TabPanel";

@Component({
  selector: "xui-tabs",
  standalone: true,
  imports: [CommonModule],
  providers: [TabsService],
  templateUrl: "./Tabs.component.html",
})
export class TabsComponent implements OnInit, AfterContentInit, TabsBaseProps {
  @Input() value?: any;
  @Input() defaultValue: any = 0;
  @Input() orientation: "horizontal" | "vertical" = "horizontal";
  @Input() variant: "standard" | "scrollable" | "fullWidth" = "standard";
  @Input() indicatorColor: "primary" | "secondary" = "primary";
  @Input() textColor: "inherit" | "primary" | "secondary" = "inherit";
  @Input() className: string = "";
  @Input("aria-label") ariaLabel: string | null = null;

  @Output() valueChange = new EventEmitter<any>();

  @ContentChildren(TabListComponent) tabLists!: QueryList<TabListComponent>;
  @ContentChildren(TabPanelComponent) tabPanels!: QueryList<TabPanelComponent>;

  constructor(private tabsService: TabsService) {}

  ngOnInit(): void {
    const initialValue =
      this.value !== undefined ? this.value : this.defaultValue;
    this.tabsService.setValue(initialValue);
    this.tabsService.setOrientation(this.orientation);
    this.tabsService.setVariant(this.variant);
    this.tabsService.setIndicatorColor(this.indicatorColor);
    this.tabsService.setTextColor(this.textColor);

    this.tabsService.value$.subscribe((value) => {
      if (this.value === undefined) {
        this.valueChange.emit(value);
      }
    });
  }

  ngAfterContentInit(): void {
    this.updateChildren();

    this.tabsService.value$.subscribe(() => {
      this.updateChildren();
    });
  }

  updateChildren(): void {
    const currentValue = this.tabsService.getValue();

    if (this.tabPanels) {
      this.tabPanels.forEach((panel) => {
        panel.active = panel.value === currentValue;
      });
    }
  }

  handleKeyDown(event: KeyboardEvent): void {
    const tabListComponent = this.tabLists.first;
    if (!tabListComponent) return;

    const tabs = tabListComponent.tabs?.toArray() || [];
    const selectedIndex = tabs.findIndex(
      (tab) => tab.value === this.tabsService.getValue(),
    );
    const tabCount = tabs.length;
    let nextIndex = selectedIndex;
    const isRtl = document.dir === "rtl";

    switch (event.key) {
      case "Home":
        nextIndex = 0;
        break;
      case "End":
        nextIndex = tabCount - 1;
        break;
      case "ArrowLeft":
        if (this.orientation === "horizontal") {
          nextIndex = Math.max(0, selectedIndex + (isRtl ? 1 : -1));
        }
        break;
      case "ArrowRight":
        if (this.orientation === "horizontal") {
          nextIndex = Math.min(tabCount - 1, selectedIndex + (isRtl ? -1 : 1));
        }
        break;
      case "ArrowUp":
        if (this.orientation === "vertical") {
          nextIndex = Math.max(0, selectedIndex - 1);
        }
        break;
      case "ArrowDown":
        if (this.orientation === "vertical") {
          nextIndex = Math.min(tabCount - 1, selectedIndex + 1);
        }
        break;
      default:
        return;
    }

    if (nextIndex !== selectedIndex && nextIndex >= 0 && nextIndex < tabCount) {
      event.preventDefault();
      const nextTab = tabs[nextIndex];
      this.tabsService.setValue(nextTab.value);

      setTimeout(() => {
        const tabElement = document.querySelector(
          `[role="tab"][data-index="${nextIndex}"]`,
        ) as HTMLElement | null;
        tabElement?.focus();
      });
    }
  }
}

